import api from '@/api';

export default {
  namespaced: true,
  state: {
    token: localStorage.getItem('token') || null,
    user: JSON.parse(localStorage.getItem('user')) || null,
    pendingVerification: null,
    error: null
  },
  getters: {
    isAuthenticated: state => !!state.token && !!state.user,
    user: state => state.user,
    pendingVerification: state => state.pendingVerification,
    error: state => state.error
  },
  mutations: {
    SET_TOKEN(state, token) {
      state.token = token;
      if (token) {
        localStorage.setItem('token', token);
      } else {
        localStorage.removeItem('token');
      }
    },
    SET_USER(state, user) {
      state.user = user;
      if (user) {
        localStorage.setItem('user', JSON.stringify(user));
      } else {
        localStorage.removeItem('user');
      }
    },
    SET_PENDING_VERIFICATION(state, data) {
      state.pendingVerification = data;
    },
    SET_ERROR(state, error) {
      state.error = error;
    },
    CLEAR_AUTH(state) {
      state.token = null;
      state.user = null;
      state.pendingVerification = null;
      state.error = null;
      localStorage.removeItem('token');
      localStorage.removeItem('user');
    }
  },
  actions: {
    init({ commit }) {
      const token = localStorage.getItem('token');
      const user = localStorage.getItem('user');
      if (token && user) {
        try {
          const userData = JSON.parse(user);
          commit('SET_TOKEN', token);
          commit('SET_USER', userData);
        } catch (error) {
          commit('CLEAR_AUTH');
        }
      } else {
        commit('CLEAR_AUTH');
      }
    },
    async register({ commit }, userData) {
      try {
        const response = await api.post('/auth/register', {
          ...userData,
          dateNaissance: userData.date_naissance
        });
        if (response.data.code === 200) {
          commit('SET_ERROR', null);
          return response.data;
        } else {
          throw new Error(response.data.message || 'Error during registration');
        }
      } catch (error) {
        console.error('Error during registration:', error);
        const errorMessage = error.response?.data?.message || error.message || 'Error during registration';
        commit('SET_ERROR', errorMessage);
        throw errorMessage;
      }
    },
    async verifyEmail({ commit }, { email, code }) {
      try {
        const response = await api.post('/auth/verify-email', { email, code });
        if (response.data.code === 200) {
          commit('SET_ERROR', null);
          return response.data;
        } else {
          throw new Error(response.data.message || 'Error during verification');
        }
      } catch (error) {
        console.error('Error during verification:', error);
        const errorMessage = error.response?.data?.message || error.message || 'Error during verification';
        commit('SET_ERROR', errorMessage);
        throw errorMessage;
      }
    },
    async resendVerificationCode({ commit }, { email }) {
      try {
        const response = await api.post('/auth/resend-code', { email });
        if (response.data.code === 200) {
          commit('SET_ERROR', null);
          return response.data;
        } else {
          throw new Error(response.data.message || 'Error resending code');
        }
      } catch (error) {
        console.error('Error resending code:', error);
        const errorMessage = error.response?.data?.message || error.message || 'Error resending code';
        commit('SET_ERROR', errorMessage);
        throw errorMessage;
      }
    },
    async login({ commit }, credentials) {
      try {
        const response = await api.post('/auth/login/initiate', {
          email: credentials.email,
          password: credentials.password
        });
        if (response.data.code === 200) {
          commit('SET_PENDING_VERIFICATION', {
            email: credentials.email,
            message: response.data.data.message || 'Please enter the verification code sent by email'
          });
          return response.data;
        } else {
          throw new Error(response.data.message || 'Error during login');
        }
      } catch (error) {
        console.error('Error during login:', error);
        const errorMessage = error.response?.data?.message || error.message || 'Error during login';
        commit('SET_ERROR', errorMessage);
        throw errorMessage;
      }
    },
    async verify2FA({ commit }, { email, code }) {
      try {
        const response = await api.post('/auth/login/verify', { email, pin: code });
        if (response.data.code === 200) {
          const { token, user } = response.data.data;
          commit('SET_TOKEN', token);
          commit('SET_USER', user);
          commit('SET_PENDING_VERIFICATION', null);
          commit('SET_ERROR', null);
          return response.data;
        } else {
          throw new Error(response.data.message || 'Error during 2FA verification');
        }
      } catch (error) {
        const errorMessage = error.response?.data?.message || error.message;
        commit('SET_ERROR', errorMessage);
        throw errorMessage;
      }
    },
    async logout({ commit }) {
      commit('CLEAR_AUTH');
    }
  }
};
